"""Independent 2009/D-G2 answers."""
import json
from pathlib import Path
YUNLI=r'''#include <bits/stdc++.h>
using namespace std;using ll=long long;struct Seg{int n;vector<ll>s;vector<int>lazy;Seg(int n):n(n),s(4*n),lazy(4*n,-1){}void apply(int v,int l,int r,int x){s[v]=1LL*(r-l+1)*x;lazy[v]=x;}void push(int v,int l,int r){if(lazy[v]<0||l==r)return;int m=(l+r)/2;apply(v*2,l,m,lazy[v]);apply(v*2+1,m+1,r,lazy[v]);lazy[v]=-1;}void setv(int v,int l,int r,int a,int b,int x){if(b<l||r<a)return;if(a<=l&&r<=b){apply(v,l,r,x);return;}push(v,l,r);int m=(l+r)/2;setv(v*2,l,m,a,b,x);setv(v*2+1,m+1,r,a,b,x);s[v]=s[v*2]+s[v*2+1];}ll get(int v,int l,int r,int a,int b){if(b<l||r<a)return 0;if(a<=l&&r<=b)return s[v];push(v,l,r);int m=(l+r)/2;return get(v*2,l,m,a,b)+get(v*2+1,m+1,r,a,b);}};int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int t;cin>>t;while(t--){int n,k,q;cin>>n>>k>>q;vector<int>a(n),freq(2*n+3);for(int i=0;i<n;i++){cin>>a[i];a[i]=a[i]-i+n;}multiset<int>counts;auto change=[&](int x,int d){if(freq[x])counts.erase(counts.find(freq[x]));freq[x]+=d;if(freq[x])counts.insert(freq[x]);};vector<int>cost(n-k+1);for(int i=0;i<n;i++){change(a[i],1);if(i>=k)change(a[i-k],-1);if(i>=k-1)cost[i-k+1]=k-*counts.rbegin();}int z=cost.size();vector<vector<pair<int,int>>>queries(z);for(int i=0,l,r;i<q;i++){cin>>l>>r;queries[l-1].push_back({r-k,i});}vector<ll>ans(q);Seg tree(z);vector<int>st;for(int l=z-1;l>=0;l--){while(!st.empty()&&cost[st.back()]>=cost[l])st.pop_back();int end=st.empty()?z-1:st.back()-1;tree.setv(1,0,z-1,l,end,cost[l]);st.push_back(l);for(auto x:queries[l])ans[x.second]=tree.get(1,0,z-1,l,x.first);}for(ll x:ans)cout<<x<<'\n';}}'''
WHY='A length-k window can be made consecutive increasing by preserving a largest group with equal a[i]-i, so its cost is k minus the maximum frequency. Precompute every window cost by sliding counts. For a query [l,r], each prefix endpoint j contributes the minimum window cost among starts l..j-k+1. Sweep l decreasing. The prefix-minimum array for starts l is obtained by assigning cost[l] until the next position with strictly smaller cost; later values remain unchanged. Find that next position by a monotonic stack, and maintain range assignment/range sum in a lazy segment tree. Answer each query as its corresponding range sum. O((n+q)log n) time, O(n+q) space. Works for both versions.'
ANSWERS=[
('2009/D','A right triangle either has a vertical side, or its right angle uses two sloped edges between the two horizontal lines. Every vertical point pair yields n-2 triangles with any third point. Without a vertical side the right-angle vertex (x,y) must have the other vertices (x-1,1-y),(x+1,1-y), because the horizontal integer offsets multiply to -1. Count these configurations directly. O(n) time and space.',r'''#include <bits/stdc++.h>
using namespace std;int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int t;cin>>t;while(t--){int n;cin>>n;vector<array<int,2>>has(n+3);for(int i=0,x,y;i<n;i++){cin>>x>>y;has[x+1][y]=1;}long long ans=0;for(int x=1;x<=n+1;x++){if(has[x][0]&&has[x][1])ans+=n-2;for(int y=0;y<2;y++)if(has[x][y]&&has[x-1][1-y]&&has[x+1][1-y])ans++;}cout<<ans<<'\n';}}'''),
('2009/E','The signed difference after i terms is 2*(i*(2k+i-1)/2)-n*(2k+n-1)/2, strictly increasing in i. Binary-search the first nonnegative value and check it and its predecessor (if valid). Arithmetic fits signed 64-bit under bounds. O(log n) time and O(1) space.',r'''#include <bits/stdc++.h>
using namespace std;using ll=long long;int main(){int t;cin>>t;while(t--){ll n,k;cin>>n>>k;ll total=n*(2*k+n-1)/2;auto diff=[&](ll i){return i*(2*k+i-1)-total;};ll lo=1,hi=n;while(lo<hi){ll mid=(lo+hi)/2;if(diff(mid)>=0)hi=mid;else lo=mid+1;}ll ans=llabs(diff(lo));if(lo>1)ans=min(ans,llabs(diff(lo-1)));cout<<ans<<'\n';}}'''),
('2009/F','Build prefix sums of a concatenated with itself. For prefix length x in the large array, full=x/n complete rotation blocks contribute full*sum(a), and rem=x%n remaining entries start at offset full%n in the doubled array. Prefix(x)=full*sum(a)+doubledPrefix[start+rem]-doubledPrefix[start]. Query by prefix(r)-prefix(l-1). O(n+q) time and O(n) space, 64-bit sums.',r'''#include <bits/stdc++.h>
using namespace std;using ll=long long;int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int t;cin>>t;while(t--){int n,q;cin>>n>>q;vector<ll>a(n),p(2*n+1);for(ll&x:a)cin>>x;for(int i=0;i<2*n;i++)p[i+1]=p[i]+a[i%n];auto pref=[&](ll x){ll full=x/n;int rem=x%n,start=full%n;return full*p[n]+p[start+rem]-p[start];};while(q--){ll l,r;cin>>l>>r;cout<<pref(r)-pref(l-1)<<'\n';}}}'''),('2009/G1',WHY,YUNLI),('2009/G2',WHY,YUNLI)]
if __name__=='__main__':
    p=Path('backend/data/bench/codeforces700_20261116/assistant_answers_v1/shard_test_000_199.jsonl')
    with p.open('a',encoding='utf-8') as out:
        for ident,explanation,code in ANSWERS:
            out.write(json.dumps({'id':ident,'split':'test','author':'current chat assistant','status':'authored','explanation':explanation,'cpp_code':code,'validation':'not executed'})+'\n')
